INSERT INTO public.items (media_type,title_en,title_ka,creator,year,description_en,genres,mood_tags,keywords,is_georgian,runtime_minutes,page_count,isbn) VALUES
('film','Repentance','მონანიება','Tengiz Abuladze',1984,'After a dead mayor''s body keeps reappearing, a woman stands trial for digging him up. A surreal allegory about tyranny, memory and the guilt of a nation.',ARRAY['drama','satire'],ARRAY['political','satirical','dark','philosophical'],ARRAY['dictatorship','allegory','memory'],true,153,NULL,NULL),
('film','The Wishing Tree','ნატვრის ხე','Tengiz Abuladze',1976,'In a pre-revolutionary Georgian village, a young woman is forced into a loveless marriage. A lyrical portrait of dreamers and the community that crushes them.',ARRAY['drama'],ARRAY['rural','melancholic','romantic','tender'],ARRAY['village','forbidden love','folklore'],true,107,NULL,NULL),
('film','Pirosmani','ფიროსმანი','Giorgi Shengelaia',1969,'The life of the self-taught painter Niko Pirosmani, who traded paintings for food and wine in old Tbilisi. Composed like his canvases, still and luminous.',ARRAY['drama','biography'],ARRAY['quiet','slow','melancholic','nostalgic'],ARRAY['painter','tbilisi','art'],true,85,NULL,NULL),
('film','Mimino','მიმინო','Georgiy Daneliya',1977,'A helicopter pilot from a mountain village dreams of flying big jets abroad. A warm comedy about friendship, homesickness and stubborn pride.',ARRAY['comedy','drama'],ARRAY['funny','nostalgic','tender','hopeful'],ARRAY['pilot','friendship','homesickness'],true,97,NULL,NULL),
('film','Blind Dates','ბრმა პაემნები','Levan Koguashvili',2013,'A shy forty-year-old history teacher in Tbilisi goes on a string of awkward blind dates. Deadpan humor meets quiet loneliness.',ARRAY['comedy','drama'],ARRAY['funny','melancholic','quiet','tender'],ARRAY['loneliness','dating','tbilisi'],true,99,NULL,NULL),
