('film','Tangerines','მანდარინები','Zaza Urushadze',2013,'During the 1992 war in Abkhazia, an Estonian farmer shelters two wounded soldiers from opposing sides. A small, humane anti-war fable.',ARRAY['drama','war'],ARRAY['quiet','hopeful','political','rural'],ARRAY['war','enemies','abkhazia'],true,87,NULL,NULL),
('film','Corn Island','სიმინდის კუნძული','Giorgi Ovashvili',2014,'An old farmer and his granddaughter plant corn on a temporary river island between warring borders. Almost wordless, ruled by water and seasons.',ARRAY['drama'],ARRAY['quiet','slow','isolating','rural'],ARRAY['river','nature','border'],true,100,NULL,NULL),
